package com.google.javascript.jscomp;

import com.google.javascript.jscomp.CheckLevel;
import com.google.javascript.jscomp.NodeTraversal.Callback;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.rhino.JSDocInfo;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.MockitoJUnitRunner;
import static com.google.javascript.jscomp.CheckGlobalThis.GLOBAL_THIS;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class CheckGlobalThis_visit_TriageGen2Test {

    private CheckGlobalThis checkGlobalThis;

    @Mock
    private NodeTraversal t;

    @Mock
    private Node n;

    @Mock
    private Node parent;

    @Mock
    private Compiler compiler;

    @Mock
    private Compiler.Problem problem;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        // Since we cannot call the constructor directly if it's private or complex, 
        // we assume we are testing an instance that has access to the 'compiler' field.
        // In a real scenario, we might use Reflection to set the private 'compiler' field.
        checkGlobalThis = new CheckGlobalThis();
        setPrivateField(checkGlobalThis, "compiler", compiler);
        setPrivateField(checkGlobalThis, "level", Compiler.Problem.Severity.ERROR);
    }

    @Test
    public void testVisit_NotThis_NotAssignLhs() {
        when(n.getType()).thenReturn(Token.NAME);

        checkGlobalThis.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_This_ShouldNotReport_NotAssignLhs() {
        when(n.getType()).thenReturn(Token.THIS);
        // Mocking shouldReportThis via a spy or by controlling the environment if possible.
        // Since we cannot easily mock the internal method 'shouldReportThis', 
        // we rely on the logic: if shouldReportThis returns false, no error is reported.
        // For this test, we assume a scenario where shouldReportThis would return false.

        // Note: In a real environment, you'd use a Spy to force shouldReportThis to return false.
        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        org.mockito.Mockito.doReturn(false).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler, never()).report(any());
    }

    @Test
    public void testVisit_This_ShouldReport_NotAssignLhs() {
        when(n.getType()).thenReturn(Token.THIS);
        when(t.makeError(any(), any())).thenReturn(problem);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(problem);
    }

    @Test
    public void testVisit_NotThis_IsAssignLhs() throws Exception {
        when(n.getType()).thenReturn(Token.NAME);
        setPrivateField(checkGlobalThis, "assignLhsChild", n);

        checkGlobalThis.visit(t, n, parent);

        assertNull(getPrivateField(checkGlobalThis, "assignLhsChild"));
    }

    @Test
    public void testVisit_This_IsAssignLhs_ShouldReport() throws Exception {
        when(n.getType()).thenReturn(Token.THIS);
        when(t.makeError(any(), any())).thenReturn(problem);
        setPrivateField(checkGlobalThis, "assignLhsChild", n);

        CheckGlobalThis spyCheck = org.mockito.Mockito.spy(checkGlobalThis);
        org.mockito.Mockito.doReturn(true).when(spyCheck).shouldReportThis(n, parent);

        spyCheck.visit(t, n, parent);

        verify(compiler).report(problem);
        assertNull(getPrivateField(checkGlobalThis, "assignLhsChild"));
    }

    // Helper methods to manipulate private fields for testing purposes
    private void setPrivateField(Object target, String fieldName, Object value) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            field.set(target, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private Object getPrivateField(Object target, String fieldName) {
        try {
            java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
            field.setAccessible(true);
            return field.get(target);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
